+
+    private SquareMatrix(int[][] values) {
+        this.values = values;
+    }
+
+    static SquareMatrix copyOf(int[][] source, String label) {
+        validateSquareMatrix(source, label);
+        return new SquareMatrix(deepCopy(source));
